entries[1233894] = { ["name"] = "Tailwind Conduit", ["text"] = "Unlimited range\nInstant\nGenerates a burst of speed on exiting combat, increasing your Movement speed by 60% for 10 sec decaying over time. Using a defensive cooldown while in combat has gusts of wind surround you, applying a shield for 8 sec equal to 30% of your missing health.\n(30s cooldown)" }
